"""Conversion of ledger exports to format v2.

Only append and delete are atomic, and the reporting service reads the index
and the files it names at any time. So a name the index holds is never
written again: a part's v2 file is written under a name the index does not
hold and published by appending an index line, which replaces the part's
earlier line for the reader. The quarantine grows by appends; it is replaced
only to drop entries, through a complete copy that a marker commits.
"""

import re
import sys

import codec
from storage import Missing

HEADER = "# ledger v2\n"
# The longest line bufio.Scanner returns; at a longer one ReadPart's scan ends.
LONGEST = 64 * 1024 - 1
SRC = re.compile(r"(.*)\|src=([0-9]+):([0-9]+)")
ENTRY = re.compile(r"([^:]*):([0-9]+):(.*)")

# Names the reporting service does not read. READY exists while NEW holds a
# complete quarantine that has to replace the present one. CLEAN exists once
# the quarantine's texts are the lines as ReadPart reads them: the shipped
# code kept the carriage return of a line that ends in CR LF.
NEW = "migrate/quarantine.new"
READY = "migrate/quarantine.ready"
CLEAN = "migrate/quarantine.clean"


def log(message):
    print(f"migrate: {message}", file=sys.stderr)


def read(store, name):
    try:
        return store.read(name)
    except Missing:
        return None


def index(store):
    """The (part, file) pairs of the index, in its order."""
    pairs = []
    for line in (read(store, "v2/index") or "").split("\n"):
        part, found, file = line.partition(" ")
        if found:
            pairs.append((part, file))
    return pairs


def settle(store):
    """Finish a replacement of the quarantine that READY committed."""
    if read(store, READY) is not None:
        if read(store, NEW) is not None:
            store.rename(NEW, "quarantine")
        store.append(CLEAN, "1\n")
        store.delete(READY)


def replace(store, text):
    store.write(NEW, text)
    store.append(READY, "1\n")
    settle(store)


def scan(export):
    """The numbered lines of an export as ReadPart's scanner reads them."""
    lines = []
    for number, raw in enumerate(export.split("\n"), 1):
        if len(raw.encode("utf-8", "surrogatepass")) > LONGEST:
            break
        lines.append((number, raw.removesuffix("\r")))
    return lines


def build(part, lines):
    """The v2 records and the quarantine entries of a part's numbered lines."""
    records, rejected = [], []
    for number, line in lines:
        if line and not line.startswith("#"):
            try:
                record = codec.decode_v1(line)
            except ValueError:
                rejected.append(f"{part}:{number}:{line}\n")
            else:
                records.append(codec.encode_v2(record, part, number) + "\n")
    return records, rejected


def convert(store, part, file, used):
    """Publish the part and remove its export; return its quarantine entries.

    file is the name the index gives the part, or None. The export decides
    while it exists. Without it the lines are those of the published file
    and of the part's quarantine entries, the file first where both hold a
    line; a file named v2/<part> is one the shipped code wrote.
    """
    export = read(store, f"v1/{part}")
    current = read(store, file) if file else None
    shipped = file == f"v2/{part}"
    quarantine = (read(store, "quarantine") or "").split("\n")
    if export is not None:
        lines = scan(export)
    else:
        found = {}
        for entry in quarantine:
            match = ENTRY.fullmatch(entry)
            if match and match[1] == part:
                found[int(match[2])] = match[3]
        for line in (current or "").split("\n"):
            match = SRC.fullmatch(line)
            if match and match[2] == part:
                text = match[1].removesuffix("\r") if shipped else match[1]
                found[int(match[3])] = text
        lines = sorted(found.items())
    records, rejected = build(part, lines)
    text = HEADER + "".join(records)
    # A rejected line enters the quarantine before the index stops naming
    # the file that holds it, and the export goes last.
    missing = [entry for entry in rejected if entry[:-1] not in quarantine]
    if missing:
        store.append("quarantine", "".join(missing))
    if text != current or (shipped and export is not None):
        serial = 1
        while f"v2/{part}.{serial}" in used:
            serial += 1
        store.write(f"v2/{part}.{serial}", text)
        store.append("v2/index", f"{part} v2/{part}.{serial}\n")
        log(f"{part} published ({len(records)} records, {len(rejected)} quarantined)")
    if export is not None:
        store.delete(f"v1/{part}")
    return rejected


def run(store):
    settle(store)
    if read(store, CLEAN) is None:
        old = read(store, "quarantine") or ""
        new = "\n".join(line.removesuffix("\r") for line in old.split("\n"))
        if new == old:
            store.append(CLEAN, "1\n")
        else:
            replace(store, new)
    pairs = index(store)
    files = dict(pairs)
    used = {file for _, file in pairs}
    exports = {name.removeprefix("v1/") for name in store.names("v1/")}
    # Published parts first: the reporting service already reads them.
    parts = sorted(exports | set(files), key=lambda part: (part not in files, part))
    log(f"start: {len(exports)} exports to convert, {len(files)} parts published")
    wanted = []
    for part in parts:
        wanted += convert(store, part, files.get(part), used)
    held = (read(store, "quarantine") or "").split("\n")
    if sorted(held) != sorted([entry[:-1] for entry in wanted] + [""]):
        replace(store, "".join(wanted))
